SELECT 'INPUT_GOV_REMEDIATION_QUALITY_V1',item->>'test_code',(item->>'test_order')::int,
       item->>'title',item->>'test_type','MANUAL','HIGH',
       '{"activation":"MANUAL_BENCHMARK_ONLY","source_authority":"CANDIDATO","automatic_decision":false}'::jsonb,
       item->'input_payload',item->'expected_output',item->'prohibited_output',
       'CANDIDATO',
       jsonb_build_object('plan','IG_CURATOR_VALIDATOR_REFACTOR_V2','unit','M7.12',
