ON CONFLICT (suite_code,test_code) DO NOTHING;

DO $m712$
DECLARE v_count int;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.lf_test_suites
    WHERE suite_code='INPUT_GOV_REMEDIATION_QUALITY_V1'
      AND status='CANDIDATO'
      AND execution_policy->>'mode'='READ_ONLY'
      AND metadata->>'source_yaml_git_blob_sha1'='cc19224692baeac113c18e0924d75d38ecebef5c'
      AND metadata->>'judge_git_blob_sha1'='bafcea6c52feaab72489fcde9c27b7cdc0f2f274'
      AND metadata->>'manifest_git_blob_sha1'='c3a824d939e317b4dbedf604bd054804ea91d436'
      AND metadata->>'non_decisional'='true'
  ) THEN
    RAISE EXCEPTION 'M7.12 suite authority/SHA mismatch';
  END IF;
  SELECT count(*) INTO v_count FROM public.lf_test_suite_cases WHERE suite_code='INPUT_GOV_REMEDIATION_QUALITY_V1';
  IF v_count<>20 THEN
    RAISE EXCEPTION 'M7.12 case count mismatch: expected 20, got %',v_count;
  END IF;
  IF EXISTS (SELECT 1 FROM public.lf_test_suite_cases WHERE suite_code='INPUT_GOV_REMEDIATION_QUALITY_V1'
      AND (status<>'CANDIDATO' OR metadata->>'source_yaml_git_blob_sha1'<>'cc19224692baeac113c18e0924d75d38ecebef5c'
      OR metadata->>'judge_git_blob_sha1'<>'bafcea6c52feaab72489fcde9c27b7cdc0f2f274')) THEN
    RAISE EXCEPTION 'M7.12 existing case authority/SHA mismatch';
  END IF;
END;
$m712$;
